mapper.select:
select coupon_id, coupon_code, coupon_name, discount_type, discount_value, min_amount, use_count, max_use, status, start_time, end_time, create_time from rental_coupon
and coupon_code like concat('%', #{couponCode}, '%') and coupon_name like concat('%', #{couponName}, '%') and status = #{status}
order by create_time desc

select coupon_id, coupon_code, coupon_name, discount_type, discount_value, min_amount,
       use_count, max_use, status, start_time, end_time, create_time
from rental_coupon where coupon_id = #{couponId}

select coupon_id, coupon_code, coupon_name, discount_type, discount_value, min_amount,
       use_count, max_use, status, start_time, end_time, create_time
from rental_coupon where coupon_code = #{couponCode}

mapper.update:
update rental_coupon
coupon_name = #{couponName}, discount_type = #{discountType}, discount_value = #{discountValue}, min_amount = #{minAmount}, max_use = #{maxUse}, status = #{status}, start_time = #{startTime}, end_time = #{endTime},
where coupon_id = #{couponId}
